export function generateSteps(input) {
  const { arr, target } = input;
  const n = arr.length;
  const jumpSize = Math.floor(Math.sqrt(n));
  const steps = [];
  let comparisons = 0;
  let jumps = 0;

  steps.push({
    type: 'info',
    msg: `Searching for ${target} in sorted array. Jump size = √${n} = ${jumpSize}`,
    indices: [],
    arr: [...arr],
    comparisons,
    jumps,
  });

  // Phase 1: Find the block
  let prev = 0;
  let curr = jumpSize;

  while (curr < n && arr[curr] < target) {
    comparisons++;
    jumps++;

    steps.push({
      type: 'jump',
      msg: `Jump to index ${curr}. Value ${arr[curr]} < target ${target}`,
      indices: [prev, curr],
      blockStart: prev,
      blockEnd: curr,
      arr: [...arr],
      comparisons,
      jumps,
    });

    prev = curr;
    curr += jumpSize;
  }

  // Phase 2: Linear search within the block
  steps.push({
    type: 'block_found',
    msg: `Block found between indices ${prev}-${Math.min(curr, n - 1)}. Starting linear search...`,
    indices: [prev],
    blockStart: prev,
    blockEnd: Math.min(curr, n - 1),
    arr: [...arr],
    comparisons,
    jumps,
  });

  let found = false;
  for (let i = prev; i < Math.min(curr, n); i++) {
    comparisons++;

    if (arr[i] === target) {
      steps.push({
        type: 'found',
        msg: `✅ Found ${target} at index ${i}!`,
        indices: [i],
        found: true,
        arr: [...arr],
        comparisons,
        jumps,
      });
      found = true;
      break;
    } else {
      steps.push({
        type: 'search',
        msg: `Linear search: checking index ${i}. Value ${arr[i]} ≠ target ${target}`,
        indices: [i],
        blockStart: prev,
        blockEnd: Math.min(curr, n - 1),
        arr: [...arr],
        comparisons,
        jumps,
      });
    }
  }

  if (!found) {
    steps.push({
      type: 'not_found',
      msg: `❌ Target ${target} not found in array`,
      indices: [],
      arr: [...arr],
      comparisons,
      jumps,
    });
  }

  return steps;
}
